INSERT INTO public.election_analysis_workbook_audit(id,year,section,record_key,source_url,source_sheet,source_row,workbook_sha256,status,incoming,existing)
SELECT x.workbook_sha256||':state:'||(x.year||':'||x.ballot||':'||x.party),x.year,'state',x.year||':'||x.ballot||':'||x.party,x.source_url,x.source_sheet,x.source_row,x.workbook_sha256,
 CASE WHEN s.year IS NULL THEN 'added' WHEN s.votes IS NOT DISTINCT FROM x.votes AND s.valid_votes IS NOT DISTINCT FROM x.valid_votes AND s.share IS NOT NULL AND abs(s.share-round(x.votes::numeric/x.valid_votes*100,5))<=0.051 THEN 'matched' ELSE 'conflict' END,to_jsonb(x),to_jsonb(s)
FROM input x LEFT JOIN public.election_analysis_state s ON s.year=x.year AND s.ballot=x.ballot AND s.party=x.party
WHERE true ON CONFLICT DO NOTHING;
