INSERT INTO public.election_analysis_workbook_audit(id,year,section,record_key,source_url,source_sheet,source_row,workbook_sha256,status,incoming,existing)
SELECT x.workbook_sha256||':totals:'||(x.year||':'||x.ballot),x.year,'totals',x.year||':'||x.ballot,x.source_url,x.source_sheet,x.source_row,x.workbook_sha256,
 CASE WHEN s.year IS NULL THEN 'added' WHEN s.election_date=x.election_date AND s.eligible=x.eligible AND s.voters=x.voters AND s.valid_votes=x.valid_votes AND s.invalid_votes=x.invalid_votes THEN 'matched' ELSE 'conflict' END,to_jsonb(x),to_jsonb(s)
FROM input x LEFT JOIN public.election_analysis_state_totals s ON s.year=x.year AND s.ballot=x.ballot
