INSERT INTO public.election_analysis_workbook_audit(id,year,section,record_key,source_url,source_sheet,source_row,workbook_sha256,status,incoming,existing)
SELECT x.workbook_sha256||':flows:'||(x.year||':'||x.previous_year||':'||x.target_party||':'||x.partner),x.year,'flows',x.year||':'||x.previous_year||':'||x.target_party||':'||x.partner,x.source_url,x.source_sheet,x.source_row,x.workbook_sha256,
